import json

def check_similarity(MAPID, DetailURL):
    # Assuming the condition is that both MAPID and DetailURL are not empty and are of the same type
    if isinstance(MAPID, str) and isinstance(DetailURL, str):
        if MAPID != "" and DetailURL != "":
            return 1
        else:
            return 0
    elif isinstance(MAPID, dict) and isinstance(DetailURL, dict):
        try:
            mapid_json = json.dumps(MAPID)
            detailurl_json = json.dumps(DetailURL)
            if mapid_json != "" and detailurl_json != "":
                return 1
            else:
                return 0
        except:
            return 0
    else:
        return 0

